function rand(a,b){return Math.floor(Math.random()*(b-a+1))+a}
function forgeItem(){const cost=forgeCost(),material=era().material;if(S.gold<cost)return toast('Not enough gold—fight an enemy or collect idle earnings.',true);if((S.resources[material]||0)<3)return toast(`Need 3 ${material}. Gather resources in instances.`,true);S.gold-=cost;S.resources[material]-=3;let roll=Math.random()+S.hammer*.035,rarity=roll>.995?'Mythic':roll>.98?'Legendary':roll>.88?'Epic':roll>.64?'Rare':'Common',idx=RARITIES.indexOf(rarity),base=(S.era+1)*5+rand(2,8)+idx*7,type=TYPES[rand(0,TYPES.length-1)],stats={Attack:rand(2,base),HP:rand(0,base*2),Crit:rand(0,4+idx),CritDamage:rand(0,10+idx*3),AttackSpeed:rand(0,5),Fire:rand(0,S.era+idx),Shadow:rand(0,S.era+idx),Lifesteal:rand(0,2+idx)},item={id:Date.now()+Math.random(),type,era:S.era,rarity,level:1,stats,attack:stats.Attack,hp:stats.HP};S.gear.push(item);S.forged++;S.xp+=12;S.quests.forge=(S.quests.forge||0)+1;updateDaily('forge');achievementCheck();animateForge();toast(`${rarity} ${type} forged!`);save();render()}
function animateForge(){const scene=document.getElementById('forgeScene'),anvil=scene.querySelector('.anvil');anvil.style.transform='rotate(-18deg) scale(1.1)';setTimeout(()=>anvil.style.transform='',170);for(let i=0;i<9;i++){let s=document.createElement('span');s.className='spark';s.textContent=['✦','✧','•'][rand(0,2)];s.style.left=rand(35,65)+'%';s.style.top=rand(42,70)+'%';s.style.setProperty('--x',rand(-60,60)+'px');scene.appendChild(s);setTimeout(()=>s.remove(),850)}}
function gearCard(g,actions=true){return `<div class="gear-item"><div class="gear-icon">${TYPEICON[g.type]||'⚔️'}</div><div class="gear-info"><b class="rarity-${g.rarity.toLowerCase()}">${g.rarity} ${g.type} <span style="color:var(--muted)">+${g.level||1}</span></b><small>${ERAS[g.era]?.name||'Stone Age'} · ATK ${g.attack} · HP ${g.hp} · Crit ${g.stats.Crit}%</small></div><div class="gear-stat">+${g.attack} ⚔</div>${actions?`<button class="icon-btn" onclick="itemActions('${g.id}')">···</button>`:''}</div>`}
function itemActions(id){let g=S.gear.find(x=>String(x.id)===id);if(!g)return;modal(`<div class="modal-head"><div><div class="eyebrow">${g.rarity} · ${ERAS[g.era].name}</div><h2>${TYPEICON[g.type]} ${g.type} +${g.level}</h2></div><button class="close" onclick="closeModal()">✕</button></div><p class="gear-detail">⚔ Attack ${g.stats.Attack} · ♥ HP ${g.stats.HP}<br>🎯 Crit chance ${g.stats.Crit}% · Crit damage ${g.stats.CritDamage}%<br>⚡ Attack speed ${g.stats.AttackSpeed}% · 🔥 Fire ${g.stats.Fire}<br>🌑 Shadow ${g.stats.Shadow} · 💚 Life steal ${g.stats.Lifesteal}%</p><div class="modal-actions"><button class="btn btn-primary" onclick="upgradeGear('${g.id}')">⬆ Upgrade</button><button class="btn btn-secondary" onclick="reforgeGear('${g.id}')">✨ Reforge</button></div><button class="btn btn-secondary btn-wide" style="margin-top:9px" onclick="salvageGear('${g.id}')">♻ Salvage for materials</button>`)}
function upgradeGear(id){let g=S.gear.find(x=>String(x.id)===id);if(!g)return;let cost=20*(g.level||1)+S.era*10;if(S.gold<cost)return toast('Not enough gold to upgrade.',true);S.gold-=cost;g.level=(g.level||1)+1;g.attack+=Math.ceil((g.attack+1)*.18);g.hp+=Math.ceil((g.hp+1)*.15);g.stats.Attack=g.attack;g.stats.HP=g.hp;S.xp+=5;toast(`${g.type} upgraded to +${g.level}!`);closeModal();save();render()}
