const DEFAULT={gold:120,gems:0,energy:20,mountEssence:0,resources:{Stone:35,Wood:30,'Iron Ore':0,Bronze:0,Steel:0,Titanium:0,'Space Metal':0,'Quantum Crystal':0},anvil:1,furnace:1,hammer:1,workshop:1,era:0,gear:[],forged:0,kills:0,bosses:0,arena:0,arenaAttempts:3,instanceRuns:{},pets:[],mounts:[],activePet:null,activeMount:null,skills:{silence:1,greed:1,lifesteal:1,rebirth:1},quests:{},achievements:[],goldEarned:0,xp:0,energyAt:Date.now(),lastTick:Date.now(),lastDaily:new Date().toDateString(),lastWeekly:Math.floor(Date.now()/604800000),sound:true,tutorial:false,claimedIdle:Date.now(),dailyClaims:{},weeklyClaims:{}};
let S=loadGame(),currentEnemy=null,activeTab='home',tutorialIndex=0,toastTimer;
function loadGame(){try{const x=JSON.parse(localStorage.getItem('forgeMasterSave')||'null');return x?{...structuredClone(DEFAULT),...x,resources:{...DEFAULT.resources,...x.resources},skills:{...DEFAULT.skills,...x.skills},instanceRuns:x.instanceRuns||{},quests:x.quests||{},dailyClaims:x.dailyClaims||{},weeklyClaims:x.weeklyClaims||{}}:structuredClone(DEFAULT)}catch(e){return structuredClone(DEFAULT)}}
function save(){S.lastTick=Date.now();localStorage.setItem('forgeMasterSave',JSON.stringify(S))}
const fmt=n=>Math.floor(n||0).toLocaleString(),cap=(n,a,b)=>Math.max(a,Math.min(b,n)),era=()=>ERAS[S.era],level=()=>Math.floor(S.xp/100)+1,rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
function power(){let gearPower=S.gear.reduce((a,g)=>a+g.attack+g.hp*.08,0),pet=PETS.find(p=>p.name===S.activePet),mount=MOUNTS.find(p=>p.name===S.activeMount);return Math.floor(12+(S.anvil-1)*11+gearPower+(pet?.kind==='attack'?12:0)+(mount?18:0))}
function production(){return Math.floor((3+S.furnace*2+S.workshop*3)*(1+(S.pets.includes('Baby Dragon')?.12:0)+(S.pets.includes('Golem')?.1:0)+(S.pets.includes('Quantum Robot')?.18:0)))}
function toast(msg,bad=false){let el=document.getElementById('toast');el.textContent=msg;el.classList.toggle('bad',bad);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
