function setText(id,value){let e=document.getElementById(id);if(e)e.textContent=value}
function updateHeader(){setText('goldTop',fmt(S.gold));setText('gemsTop',fmt(S.gems));setText('energyTop',fmt(S.energy));setText('energyPage',fmt(S.energy));setText('eraChip',era().icon+' '+era().name);setText('arenaTop',fmt(S.arena));setText('powerLabel',fmt(power()));setText('forgedLabel',fmt(S.forged));setText('arenaLabel',fmt(S.arena));setText('productionLabel','+'+fmt(production())+' 🪙 / min');setText('forgeLevelLabel','Workshop Lv. '+S.workshop);setText('workshopHeroLevel',S.workshop);setText('goldEarned',fmt(S.goldEarned));setText('playerLevel',level());setText('profilePower',fmt(power()));setText('gemsPage',fmt(S.gems));setText('gearCount',S.gear.length);setText('petCount',S.pets.length+' / 5 discovered');setText('mountCount',S.mounts.length+' / 5 discovered');setText('bossesDefeated',S.bosses);setText('forgeCostLabel','· '+forgeCost()+' 🪙');setText('arenaRank',S.arena>500?'Gold II':S.arena>200?'Silver I':S.arena>50?'Bronze I':'Bronze III');setText('arenaAttempts',S.arenaAttempts+' / 3');setText('storageLabel','Storage '+fmt(Object.values(S.resources).reduce((a,b)=>a+b,0))+' / '+(500+S.workshop*200));setText('soundToggle',S.sound?'On':'Off');let away=Math.min(8*60*60*1000,Math.max(0,Date.now()-S.claimedIdle));setText('idleLabel',away<60000?'Ready to collect':Math.floor(away/60000)+' min ready')}
function forgeCost(){return 18+S.forged*3+S.era*8}
function renderHome(){setText('heroSubtitle',['Turn raw stone into a legend.','Bronze shines brighter in your hands.','A kingdom awaits your craftsmanship.','Shape steel for a changing world.','Reach beyond the stars.','Forge reality itself.'][S.era]);setText('eraQuestLabel',era().name+' story');setText('eraProgressText',Math.min(3,S.kills)+' / 3');document.getElementById('eraProgressBar').style.width=Math.min(100,S.kills/3*100)+'%';document.getElementById('eraTrack').innerHTML=ERAS.map((e,i)=>`<div class="era-dot ${i<S.era?'done':i===S.era?'current':''}"><i></i>${e.name.replace(' Age','')}</div>`).join('');setText('forgeHint',`Requires ${forgeCost()} gold · Your gear improves every battle.`);document.getElementById('latestGear').innerHTML=S.gear.length?gearCard(S.gear[S.gear.length-1],false):'<div class="empty">Forge your first item to see it displayed here.</div>';document.getElementById('resourceGrid').innerHTML=RESOURCES.map(r=>`<div class="resource-tile"><span>${ICONS[r]}</span><small>${r}</small><b>${fmt(S.resources[r]||0)}</b></div>`).join('')+`<div class="resource-tile"><span>🪙</span><small>Gold</small><b>${fmt(S.gold)}</b></div><div class="resource-tile"><span>💎</span><small>Gems</small><b>${fmt(S.gems)}</b></div><div class="resource-tile"><span>🐎</span><small>Mount Essence</small><b>${fmt(S.mountEssence)}</b></div><div class="resource-tile"><span>⚡</span><small>Energy</small><b>${fmt(S.energy)}</b></div>`}
function addResource(name,n){let limit=500+S.workshop*200,total=Object.values(S.resources).reduce((a,b)=>a+b,0);S.resources[name]=Math.min((S.resources[name]||0)+n,Math.max(0,limit-total))}
function forgeItem(){let cost=forgeCost(),material=era().material;if(S.gold<cost)return toast('Not enough gold—fight an enemy or collect idle earnings.',true);if((S.resources[material]||0)<3)return toast(`Need 3 ${material}. Gather resources in instances.`,true);S.gold-=cost;S.resources[material]-=3;let roll=Math.random()+S.hammer*.035,rarity=roll>.995?'Mythic':roll>.98?'Legendary':roll>.88?'Epic':roll>.64?'Rare':'Common',idx=RARITIES.indexOf(rarity),base=(S.era+1)*5+rand(2,8)+idx*7,type=TYPES[rand(0,TYPES.length-1)],stats={Attack:rand(2,base),HP:rand(0,base*2),Crit:rand(0,4+idx),CritDamage:rand(0,10+idx*3),AttackSpeed:rand(0,5),Fire:rand(0,S.era+idx),Shadow:rand(0,S.era+idx),Lifesteal:rand(0,2+idx)},item={id:Date.now()+Math.random(),type,era:S.era,rarity,level:1,stats,attack:stats.Attack,hp:stats.HP};S.gear.push(item);S.forged++;S.xp+=12;S.quests.forge=(S.quests.forge||0)+1;updateDaily('forge');achievementCheck();animateForge();toast(`${rarity} ${type} forged!`);save();render()}
