function renderWorkshop(){let upgrades=[['anvil','Anvil','⚒️','Unlocks the next era and its forging recipes.'],['furnace','Furnace','🔥','Raises idle gold production and speeds workshop crafting.'],['hammer','Hammer','🔨','Improves the odds of rare and better gear.'],['workshop','Workshop','🏠','Boosts idle income and resource storage.']];document.getElementById('upgradeGrid').innerHTML=upgrades.map(([key,name,icon,desc])=>{let cost=upgradeCost(key),lv=S[key],disabled=key==='anvil'&&(lv>=6||S.era>=lv||S.kills<3);return `<section class="card inner-card"><div class="card-head"><div class="card-title">${icon} ${name}</div><span class="badge">Lv. ${lv}</span></div><p class="subtle" style="line-height:1.55;min-height:34px">${desc}</p><div class="stat-row"><span>Next level cost</span><b>🪙 ${fmt(cost)}</b></div>${key==='anvil'?`<div class="stat-row"><span>Era capacity</span><b>${ERAS[Math.min(5,lv-1)].name}</b></div>`:''}<button class="btn btn-primary btn-wide" style="margin-top:13px" ${disabled?'disabled':''} onclick="upgradeStation('${key}')">Upgrade ${name}</button></section>`}).join('');document.getElementById('workshopPerks').innerHTML=`<div class="list-row"><span>Idle gold production</span><b>+${production()} / minute</b></div><div class="list-row"><span>Resource storage capacity</span><b>${500+S.workshop*200}</b></div><div class="list-row"><span>Rare gear chance</span><b>${Math.min(50,12+S.hammer*3)}%</b></div><div class="list-row"><span>Next era requirement</span><b>${S.era===5?'All eras unlocked':`3 frontier victories + Anvil Lv. ${S.era+2}`}</b></div>`}
