function upgradeStation(key){if(!['anvil','furnace','hammer','workshop'].includes(key))return;let cost=upgradeCost(key);if(key==='anvil'&&(S[key]>=6||S.era>=S[key]||S.kills<3))return toast('Win 3 frontier battles in this era before upgrading the Anvil.',true);if(S.gold<cost)return toast(`Need ${cost} gold for this upgrade.`,true);S.gold-=cost;S[key]++;if(key==='anvil'){S.era=S[key]-1;S.kills=0;currentEnemy=null;toast(`${era().name} unlocked! New recipes await.`)}else toast(`${key[0].toUpperCase()+key.slice(1)} upgraded to level ${S[key]}!`);S.xp+=8;save();render()}

