function renderCollection(){document.getElementById('gearInventory').innerHTML=S.gear.length?S.gear.slice().reverse().map(g=>gearCard(g)).join(''):'<div class="empty">No gear yet. Forge or explore to find equipment.</div>';document.getElementById('petCollection').innerHTML=PETS.map(p=>`<div class="card inner-card"><div style="font-size:30px">${S.pets.includes(p.name)?p.icon:'❔'}</div><b>${S.pets.includes(p.name)?p.name:'Undiscovered'}</b><small class="subtle">${p.bonus}</small><button class="btn ${S.activePet===p.name?'btn-primary':'btn-secondary'} btn-wide" style="margin-top:8px" ${!S.pets.includes(p.name)?'disabled':''} onclick="setPet('${p.name}')">${S.activePet===p.name?'Active':'Equip'}</button></div>`).join('');document.getElementById('mountCollection').innerHTML=MOUNTS.map(m=>{let got=S.mounts.includes(m.name);return `<div class="card inner-card"><div style="font-size:30px">${got?m.icon:'❔'}</div><b>${got?m.name:'Undiscovered Mount'}</b><small class="subtle">${m.attack} attack · ${m.speed} speed</small>${got?`<button class="btn ${S.activeMount===m.name?'btn-primary':'btn-secondary'} btn-wide" style="margin-top:8px" onclick="setMount('${m.name}')">${S.activeMount===m.name?'Active':'Equip'}</button>`:`<button class="btn btn-secondary btn-wide" style="margin-top:8px" onclick="buyMount('${m.name}')">Tame · ${m.essence} essence</button>`}</div>`}).join('')}
