const ACHIEVEMENTS=[{id:'firstForge',label:'First Spark · Forge 1 item',goal:1,get:()=>S.forged,reward:3},{id:'smith10',label:'Master Smith · Forge 10 items',goal:10,get:()=>S.forged,reward:5},{id:'battle10',label:'Frontier Hero · Win 10 battles',goal:10,get:()=>S.quests.victory||0,reward:5},{id:'boss1',label:'Giant Slayer · Defeat an era boss',goal:1,get:()=>S.bosses,reward:7},{id:'explorer',label:'Pathfinder · Complete 10 expeditions',goal:10,get:()=>Object.values(S.instanceRuns).reduce((a,b)=>a+b,0),reward:5},{id:'mount1',label:'Stable Keeper · Tame a mount',goal:1,get:()=>S.mounts.length,reward:5},{id:'pet1',label:'Friend of Beasts · Find a pet',goal:1,get:()=>S.pets.length,reward:3},{id:'arena100',label:'Contender · Reach 100 arena points',goal:100,get:()=>S.arena,reward:8}];
function achievementCheck(){for(let a of ACHIEVEMENTS)if(!S.achievements.includes(a.id)&&a.get()>=a.goal){S.achievements.push(a.id);S.gems+=a.reward;toast(`Achievement unlocked: ${a.label.split(' · ')[0]}! +${a.reward} gems`)}save()}
function updateDaily(kind){S.dailyProgress=S.dailyProgress||{};S.dailyProgress[kind]=(S.dailyProgress[kind]||0)+1}
