function renderQuests(){resetPeriods();let main=document.getElementById('mainQuestList');setText('mainQuestCount',`${Math.min(3,S.kills)} / 3`);main.innerHTML=`<div class="list-row"><div><b>${era().icon} ${era().name}: Frontier victories</b><small class="subtle" style="display:block">Defeat 3 enemies, then challenge the era boss.</small></div><b>${Math.min(S.kills,3)} / 3</b></div><div class="list-row"><div><b>Defeat ${era().boss}</b><small class="subtle" style="display:block">Win the boss battle to complete this era story.</small></div><b>${S.bosses>S.era?'Complete':'In progress'}</b></div><div class="list-row"><div><b>Upgrade the Anvil</b><small class="subtle" style="display:block">Unlock the next era after your story victory.</small></div><b>Lv. ${S.anvil}</b></div>`;document.getElementById('dailyQuestList').innerHTML=DAILY.map(q=>{let n=(S.dailyProgress||{})[q.id]||0,done=n>=q.goal,claimed=!!S.dailyClaims[q.id];return `<div class="list-row"><div><b>${q.label}</b><small class="subtle" style="display:block">${Math.min(n,q.goal)} / ${q.goal} · reward 45 gold + XP</small></div><button class="btn ${claimed?'btn-secondary':'btn-primary'}" onclick="claimDaily('${q.id}')" ${!done||claimed?'disabled':''}>${claimed?'Claimed':'Claim'}</button></div>`}).join('');let weeklyGoal=(S.weeklyBase||0)+10,weeklyN=Object.values(S.instanceRuns).reduce((a,b)=>a+b,0);document.getElementById('weeklyQuestList').innerHTML=`<div class="list-row"><div><b>Weekly Explorer</b><small class="subtle" style="display:block">${Math.max(0,weeklyN-(S.weeklyBase||0))} / 10 expeditions · reward 250 gold + XP</small></div><button class="btn btn-primary" onclick="claimWeekly()" ${weeklyN<weeklyGoal||S.weeklyClaims.done?'disabled':''}>${S.weeklyClaims.done?'Claimed':'Claim'}</button></div>`;document.getElementById('achievementList').innerHTML=ACHIEVEMENTS.map(a=>{let got=S.achievements.includes(a.id),n=a.get();return `<div class="list-row"><div><b>${got?'🏅':'🔒'} ${a.label}</b><small class="subtle" style="display:block">${Math.min(n,a.goal)} / ${a.goal} · reward ${a.reward} gems</small></div><span class="badge">${got?'Earned':'Achievement'}</span></div>`}).join('');setText('dailyTimer','Daily rewards reset each day')}

function renderProfile(){setText('soundToggle',S.sound?'On':'Off')}
function modal(html){let overlay=document.getElementById('modalOverlay'),content=document.getElementById('modalContent');content.innerHTML=html;overlay.classList.add('open')}
function closeModal(){document.getElementById('modalOverlay').classList.remove('open')}
function showEras(){modal(`<div class="modal-head"><div><div class="eyebrow">YOUR JOURNEY</div><h2>Six eras of forging</h2></div><button class="close" onclick="closeModal()">✕</button></div><div class="era-modal-list">${ERAS.map((e,i)=>`<div class="list-row"><b>${e.icon} ${e.name}</b><span class="badge">${i<S.era?'Unlocked':i===S.era?'Current':'Locked'}</span></div>`).join('')}</div>`)}
function showTutorial(force=false){if(!force&&S.tutorial)return;tutorialIndex=0;document.getElementById('tutorial').classList.add('show');drawTutorial()}
const TUTORIAL_STEPS=[['⚒️','WELCOME · 1 OF 3','Welcome, Forge Master','Craft gear, grow your workshop, and bring a new age to life.'],['⚔️','BATTLE · 2 OF 3','Build your legend','Defeat three frontier enemies, then challenge the era boss. Upgrade your Anvil to unlock the next age.'],['🗺️','EXPLORE · 3 OF 3','Gather and grow','Instances cost Energy and reward materials. Mystic Stable is the only source of Mount Essence. Gems are earned only through achievements.']];
function drawTutorial(){let [icon,step,title,text]=TUTORIAL_STEPS[tutorialIndex];setText('tutorialIcon',icon);setText('tutorialStep',step);setText('tutorialTitle',title);setText('tutorialText',text);document.querySelectorAll('.tutorial-dots i').forEach((d,i)=>d.classList.toggle('on',i===tutorialIndex));setText('tutorialNext',tutorialIndex===2?'Start forging →':'Continue →')}
function nextTutorial(){if(tutorialIndex<TUTORIAL_STEPS.length-1){tutorialIndex++;drawTutorial()}else skipTutorial()}
function skipTutorial(){document.getElementById('tutorial').classList.remove('show');S.tutorial=true;save()}
function claimIdle(){let now=Date.now(),elapsed=Math.min(8*60*60*1000,Math.max(0,now-S.claimedIdle)),minutes=Math.floor(elapsed/60000),amount=minutes*production();if(amount<=0)return toast('No idle earnings yet—check back in a minute.',true);gainGold(amount);S.claimedIdle=now;toast(`Collected ${fmt(amount)} idle gold!`);save();render()}
function regenerateEnergy(){let now=Date.now(),elapsed=Math.max(0,now-(S.energyAt||now)),units=Math.floor(elapsed/480000);if(units>0){S.energy=Math.min(20,S.energy+units);S.energyAt+=units*480000}if(S.energy>=20)S.energyAt=now}
function resetPeriods(){let today=new Date().toDateString(),week=Math.floor(Date.now()/604800000);if(S.lastDaily!==today){S.lastDaily=today;S.dailyClaims={};S.dailyProgress={};S.arenaAttempts=3}if(S.lastWeekly!==week){S.lastWeekly=week;S.weeklyClaims={};S.weeklyProgress=0;S.weeklyBase=Object.values(S.instanceRuns).reduce((a,b)=>a+b,0)}}
function updateDaily(kind){S.dailyProgress=S.dailyProgress||{};S.dailyProgress[kind]=(S.dailyProgress[kind]||0)+1;S.weeklyProgress=(S.weeklyProgress||0)+(kind==='instance'?1:0)}
function toggleSound(){S.sound=!S.sound;save();render();toast(`Sound ${S.sound?'on':'off'}.`)}
function confirmReset(){modal(`<div class="modal-head"><div><div class="eyebrow">START FRESH</div><h2>Reset your save?</h2></div><button class="close" onclick="closeModal()">✕</button></div><p class="subtle">This permanently removes all progress stored on this device.</p><div class="modal-actions"><button class="btn btn-secondary" onclick="closeModal()">Keep progress</button><button class="btn btn-primary" onclick="resetSave()">Reset save</button></div>`)}
function resetSave(){localStorage.removeItem('forgeMasterSave');S=structuredClone(DEFAULT);currentEnemy=null;closeModal();save();render();showTutorial();toast('A fresh adventure begins!')}
function initialize(){resetPeriods();regenerateEnergy();let elapsed=Math.min(8*60*60*1000,Math.max(0,Date.now()-(S.lastTick||Date.now())));if(elapsed>60000){let offline=Math.floor(elapsed/60000*production());gainGold(offline)}S.lastTick=Date.now();if(!S.weeklyBase)S.weeklyBase=Object.values(S.instanceRuns).reduce((a,b)=>a+b,0);render();save();if(!S.tutorial)showTutorial();setInterval(()=>{let before=S.energy;regenerateEnergy();if(before!==S.energy){save();render()}},15000);setInterval(()=>{resetPeriods();renderQuests();save()},60000);setInterval(save,30000)}
document.addEventListener('DOMContentLoaded',initialize);

